<?php

namespace App\Domain\Content\Http\Controllers;

use Illuminate\Http\RedirectResponse;

/**
 * Visitor-parity URL compatibility (owner, 2026-11-06; decision-log #102) — the main website (Gen 2) serves the
 * item page's comment pages at `khotab-item-{id}-page-{n}.htm` (`.htaccess:216` → `khotab/item.php?id=&page=`;
 * generated by `khotab/item.php:413`'s `PS_Pagination(…, 'khotab-item-{id}-page-#.htm')`). Laravel serves the same
 * comment pages at `khotab-item-{id}.htm?page={n}` (`KhotabItemController::show()`).
 *
 * The mapping is one-to-one, so the redirect is permanent: both sides number pages from 1, show 10 comments a page,
 * `view = 1`, newest first (Gen 2 `item.php:87-89, :371-372`; Laravel `paginate(10, …, 'page')`). Page 0 is the
 * first page on Gen 2 (`item.php:88`), so it goes to the canonical URL without a query. No page is rendered here —
 * the canonical route keeps every visibility rule (hidden items 404 for visitors there).
 */
class KhotabItemLegacyCommentPageRedirectController
{
    public function __invoke(int $khotab, int $page): RedirectResponse
    {
        $parameters = ['khotab' => $khotab];

        if ($page > 0) {
            $parameters['page'] = $page;
        }

        return redirect()->route('khotab.item.show', $parameters, 301);
    }
}
